package com.smartinventory.controller;
import com.smartinventory.dto.*; import com.smartinventory.model.*; import com.smartinventory.repository.*; import com.smartinventory.service.InventoryService;
import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
import java.util.*;
@RestController @RequestMapping("/api/orders")
public class OrderController {
 private final PurchaseOrderRepository orders; private final SupplierRepository suppliers; private final WarehouseRepository warehouses; private final ProductRepository products; private final InventoryService inventory;
 public OrderController(PurchaseOrderRepository o,SupplierRepository s,WarehouseRepository w,ProductRepository p,InventoryService i){orders=o;suppliers=s;warehouses=w;products=p;inventory=i;}
 @GetMapping public List<Map<String,Object>> all(){return orders.findAll().stream().map(this::map).toList();}
 @PostMapping @Transactional public Map<String,Object> create(@Valid @RequestBody CreateOrderRequest r){PurchaseOrder o=new PurchaseOrder();o.setOrderNumber(r.orderNumber());o.setSupplier(suppliers.findById(r.supplierId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Supplier not found")));o.setWarehouse(warehouses.findById(r.warehouseId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Warehouse not found")));o.setNotes(r.notes());for(OrderItemRequest i:r.items()){PurchaseOrderItem item=new PurchaseOrderItem();item.setProduct(products.findById(i.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Product not found")));item.setQuantity(i.quantity());item.setUnitPrice(i.unitPrice());o.addItem(item);}return map(orders.save(o));}
 @PutMapping("/{id}/status") @Transactional public Map<String,Object> status(@PathVariable Long id,@Valid @RequestBody StatusRequest r){PurchaseOrder o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));OrderStatus old=o.getStatus();if(old==OrderStatus.RECEIVED||old==OrderStatus.CANCELLED)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This order is already closed");if(r.status()==OrderStatus.RECEIVED){for(PurchaseOrderItem i:o.getItems())inventory.stock(new StockRequest(i.getProduct().getId(),o.getWarehouse().getId(),i.getQuantity(),"Received against "+o.getOrderNumber()),MovementType.STOCK_IN);}if(r.status()==OrderStatus.CANCELLED&&old==OrderStatus.RECEIVED)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Received orders cannot be cancelled");o.setStatus(r.status());o.setNotes(r.notes()==null?o.getNotes():r.notes());return map(orders.save(o));}
 @DeleteMapping("/{id}") public void delete(@PathVariable Long id){PurchaseOrder o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(o.getStatus()==OrderStatus.RECEIVED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Received orders cannot be deleted");orders.delete(o);}
 private Map<String,Object> map(PurchaseOrder o){Map<String,Object>m=new LinkedHashMap<>();m.put("id",o.getId());m.put("orderNumber",o.getOrderNumber());m.put("supplierId",o.getSupplier().getId());m.put("supplierName",o.getSupplier().getName());m.put("warehouseId",o.getWarehouse().getId());m.put("warehouseName",o.getWarehouse().getName());m.put("status",o.getStatus());m.put("notes",o.getNotes());m.put("createdAt",o.getCreatedAt());m.put("total",o.getTotal());m.put("items",o.getItems().stream().map(i->Map.of("productId",i.getProduct().getId(),"productName",i.getProduct().getName(),"quantity",i.getQuantity(),"unitPrice",i.getUnitPrice())).toList());return m;}
}
